// Casa um label bruto do backend (dimensão `regions` da Brandwatch — texto
// exato nunca confirmado contra um payload real, ver ressalva em
// `get_region_breakdown`/`foundation/data-model.md`) contra um dos 27
// estados — por nome completo, por sigla (UF) e, em último caso, por
// substring (cobre formatos como "BRA.SP", "SP", "São Paulo" apontando pro
// mesmo estado). Extraído de `brazil-sentiment-map.tsx` (2026-07-14) pra ser
// reusado também pela tabela do mesmo widget ("Sentimento por estado") —
// antes só o mapa resolvia o nome amigável, a tabela mostrava o label bruto.
function normalize(value: string): string {
  return value
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toLowerCase()
    .trim();
}

export function findBrazilState(label: string): BrazilStateShape | undefined {
  const norm = normalize(label);
  // Último segmento alfanumérico (separado por ".", "-", "_", espaço) —
  // cobre formatos tipo "BRA.SP"/"BR-SP" apontando pra UF "SP", sem exigir
  // que o texto inteiro seja só a sigla.
  const lastSegment = norm.split(/[^a-z0-9]+/).filter(Boolean).pop() ?? norm;
  return (
    BRAZIL_STATES.find((s) => normalize(s.name) === norm) ??
    BRAZIL_STATES.find((s) => s.code.toLowerCase() === norm) ??
    BRAZIL_STATES.find((s) => s.code.toLowerCase() === lastSegment) ??
    BRAZIL_STATES.find((s) => norm.includes(normalize(s.name)) || normalize(s.name).includes(norm))
  );
}
